def group_by_first(words):
    """Map each first letter to the list of words starting with it.
    Skip empty strings.

    >>> group_by_first(['apple', 'banana', 'avocado'])
    {'a': ['apple', 'avocado'], 'b': ['banana']}
    >>> group_by_first([])
    {}
    """
    pass

solution:
def group_by_first(words):
    groups = {}
    for w in words:
        if w == '':
            continue
        first = w[0]
        if first not in groups:
            groups[first] = []
        groups[first].append(w)
    return groups

def max_key(d):
    if not d:
        return None
    best_val = max(d.values())
    return min(k for k in d if d[k] == best_val)
